/**
 * Normalize URL and extract email from webhook payload
 */
const urlFields = ['Landing Page Url', 'url', 'link'];

items.forEach(item => {
  // Handle URL normalization
  urlFields.forEach(field => {
    const original = item.json[field];
    if (typeof original !== 'string' || original.trim() === '') return;

    // Check if URL has scheme
    const hasScheme = /^(https?:\/\/)/i.test(original);

    // Add https:// if missing
    if (!hasScheme) {
      item.json[field] = `https://${original}`;
    }
  });

  // Ensure we have a normalized URL field
  item.json.normalizedUrl = item.json['Landing Page Url'] || item.json.url || '';
  item.json.userEmail = item.json['Email'] || item.json.email || '';
});

return items;

